[{"id": "job_device_binding", "weight": 0.047619047619047616, "description": "Bind A, B and D to station one at 12 dots/mm and C to station two at 8 dots/mm, and select only collection modes supported at the assigned station. Equivalent tables are accepted. Binary."}, {"id": "job_consumables", "weight": 0.047619047619047616, "description": "Bind each job to print method, gap media and ribbon state: A uses R80 external-coated ribbon, B is direct thermal with ribbon removed, C uses R110 external-coated ribbon, ribbons cover media width, and R110-I is not substituted. Binary."}, {"id": "d_capability_hold", "weight": 0.047619047619047616, "description": "For D, distinguish 108 mm media transport/peel capacity from the 104 mm printable-image limit and 1296 requested dots versus 1248 maximum, and hold the original job rather than clipping or releasing it. Binary."}, {"id": "resolution_and_format", "weight": 0.047619047619047616, "description": "Use native 12 dots/mm for station one and 8 dots/mm for station two, reject direct reuse of the old 203 dpi station-one format on 300 dpi, and require verification of resulting physical image dimensions. Binary."}, {"id": "host_power_head_state", "weight": 0.047619047619047616, "description": "Stop host traffic and keep the job paused during setup/calibration, cool the print head before access, and if power is cycled save needed state before shutdown and restore the current job's temporary format/settings after restart. Binary."}, {"id": "media_path_and_guides", "weight": 0.047619047619047616, "description": "Discard unusable leader, load the roll inward, route media under the tension section through the sensor and under the head, and set guides to touch without clamping. Binary."}, {"id": "ribbon_path_and_mode", "weight": 0.047619047619047616, "description": "For transfer work route the matching ribbon to the take-up spindle and remove slack; for B remove ribbon; then lock the head and close the media door. Binary."}, {"id": "wizard_and_full_calibration", "weight": 0.047619047619047616, "description": "Set method, gap type, width and collection mode through the supported setup path, perform automatic calibration after a relevant media size/type change, and print a test label before production. A short check must not replace required sensor recalibration. Binary."}]
